  CW += c[22] * 28.054000;  // C2H4
  CW += c[23] * 27.046000;  // C2H3
  CW += c[24] * 58.036000;  // CHOCHO
  CW += c[25] * 59.044000;  // C2H3OO
  CW += c[26] * 42.037000;  // CHCHO
  CW += c[27] * 26.038000;  // C2H2
  CW += c[28] * 45.061000;  // C2H5O
  CW += c[29] * 45.061000;  // PC2H4OH
  CW += c[30] * 77.059000;  // O2C2H4OH
  CW += c[31] * 43.045000;  // CH2CHO
  CW += c[32] * 42.037000;  // CH2CO
  CW += c[33] * 41.029000;  // HCCO
  CW += c[34] * 44.097000;  // C3H8
  CW += c[35] * 43.089000;  // IC3H7
  CW += c[36] * 43.089000;  // NC3H7
  CW += c[37] * 75.087000;  // C3H6OOH1-2
  CW += c[38] * 75.087000;  // C3H6OOH1-3
  CW += c[39] * 42.081000;  // C3H6
  CW += c[40] * 41.073000;  // C3H5-A
  CW += c[41] * 57.072000;  // CH3CHCHO
