  dqdc[37] = dcdc_fac;
  dqdc[38] = dcdc_fac;
  dqdc[39] = dcdc_fac;
  dqdc[40] = dcdc_fac;
  dqdc[41] = dcdc_fac;
  dqdc[42] = dcdc_fac;
  dqdc[43] = dcdc_fac;
  dqdc[44] = dcdc_fac;
  dqdc[45] = dcdc_fac;
  dqdc[46] = dcdc_fac;
  dqdc[47] = dcdc_fac;
  dqdc[48] = dcdc_fac;
  dqdc[49] = dcdc_fac;
  dqdc[50] = dcdc_fac;
  dqdc[51] = dcdc_fac;
  dqdc[52] = dcdc_fac;
  dqdc[53] = dcdc_fac;
  dqdc[54] = dcdc_fac;
  dqdc[55] = dcdc_fac;
  dqdc[56] = dcdc_fac;
  dqdc[57] = dcdc_fac;
  dqdc[58] = dcdc_fac;
  dqdc[59] = dcdc_fac;
  dqdc[60] = dcdc_fac;
  dqdc[61] = dcdc_fac;
  dqdc[62] = dcdc_fac;
  dqdc[63] = dcdc_fac;
  dqdc[64] = dcdc_fac;
  dqdc[65] = dcdc_fac;
  for (int k = 0; k < 66; k++) {
    J[67 * k + 2] -= dqdc[k];
    J[67 * k + 3] -= dqdc[k];
    J[67 * k + 8] += dqdc[k];
  }
  J[4424] -= dqdT; // dwdot[H]/dT
  J[4425] -= dqdT; // dwdot[O2]/dT
